import { escapeHtml as esc } from './message-format.js';
import { statusPill } from './ticket-view.js';
import { projectWorkflows } from './customer-workflows.js';
import { projectPrivacy } from './customer-privacy.js';

/** Project state is discarded on navigation/sign-out. API secrets are shown once. */
export function createCustomerProjects({root, api, session, getMe, backendId}) {
  let generation = 0, projects = [];
  const token = () => session.load();
  const service = `https://${backendId}.icp.net/support/v1`;
  const base = () => new URL('.', location.href).href;
  const active = stamp => stamp === generation && getMe() && getMe().role !== 'requester';
  function clear() { generation++; root.replaceChildren(); projects = []; }
  const notice = text => { const el=root.querySelector('[data-status]'); if(el) el.textContent=text; };
  const input = (label,id,value='',extra='') => `<label for="${id}">${label}</label><input id="${id}" ${extra.includes("type=")?"":"type=\"text\""} value="${esc(value)}" ${extra}>`;
  const section = (title,body) => `<section class="card customer-section"><h3>${title}</h3>${body}</section>`;
  async function run(button, work, done) {
    const stamp=generation; button.disabled=true; notice('Saving…');
    try { const r=await work(); if(!active(stamp))return; if(r===false||r?.ok===false)throw new Error(r?.detail||'The change could not be saved.'); notice('Saved'); await done?.(r); }
    catch(e) { if(active(stamp))notice(e.message||'Connection interrupted. Please retry.'); }
    finally { if(button.isConnected)button.disabled=false; }
  }
  async function show(id='', mode='') {
    const stamp=++generation; root.innerHTML='<p class="lead" role="status">Loading customer support…</p>';
    if(!getMe()||getMe().role==='requester'){clear();return;}
    try {
      projects=await api().listCustomerProjects(token()); if(!active(stamp))return;
      if(id==='new'&&getMe().role==='admin')return editor(null);
      const p=projects.find(p=>String(p.id)===id);
      if(!id)return overview();
      if(!p){root.innerHTML='<h2>Project unavailable</h2><p>Your Hub account may not have access to this support team.</p>';return;}
      if(mode==='types'&&getMe().role==='admin')return await projectWorkflows({root,project:p,api,token,active:()=>active(stamp)&&getMe()?.role==='admin',reload:()=>show(String(p.id),'types')});
      if(mode==='settings'&&getMe().role==='admin')return editor(p);
      await workspace(p,stamp);
    } catch(e) { if(active(stamp))root.innerHTML='<h2>Customer support is unavailable</h2><p>Please reload to try again.</p>'; }
  }
  function overview() {
    root.innerHTML=`<div class="page-heading"><div><span class="eyebrow">CUSTOMER SUPPORT</span><h2>A space for each product.</h2><p class="lead">Separate customers, conversations and support teams. Together in Desk.</p></div>${getMe().role==='admin'?'<a class="button primary" href="#/customers/new">New project +</a>':''}</div><div class="customer-project-grid">${projects.map(p=>`<article class="card customer-project"><span class="pill ${p.enabled?'':'off'}">${p.enabled?'Accepting requests':'Intake paused'}</span><h3><a href="#/customers/${p.id}">${esc(p.name)}</a></h3><p>${esc(p.description||'Customer support for this product.')}</p><div class="customer-project-footer"><span>${esc(p.group||'Hub admins only')}</span><a href="#/customers/${p.id}">Open workspace →</a></div></article>`).join('')||'<div class="card empty"><h3>Give your customers a place to ask.</h3><p>Create a project, choose its Hub support group and share a form or connect your product.</p></div>'}</div><p class="kv">Project access follows Hub. Desk admins can see every project; agents need membership in its support group.</p>`;
  }
  async function workspace(p,stamp) {
    root.innerHTML=`<a class="back-link" href="#/customers">← Customer projects</a><div class="page-heading"><div><span class="eyebrow">CUSTOMER SUPPORT</span><h2>${esc(p.name)}</h2><p class="lead">${esc(p.description||'Every customer conversation, with a clear next step.')}</p></div>${getMe().role==='admin'?`<a class="button" href="#/customers/${p.id}/settings">Project & integrations</a>`:''}</div>${!p.enabled?'<div class="card">New requests are paused. Existing conversations remain available.</div>':''}<div data-oncall-module></div><div class="customer-toolbar"><div class="seg" id="customerFilter"><button data-view="open" class="active">Active</button><button data-view="mine">Assigned to me</button><button data-view="unassigned">Unassigned</button><button data-view="done">Completed</button><button data-view="all">All</button></div><input type="text" id="customerSearch" aria-label="Search this project" placeholder="Search this project…"><span data-status role="status"></span></div><div class="card flat"><div class="table-scroll"><table><thead><tr><th>Request</th><th>Customer</th><th>Status</th><th>Assigned to</th></tr></thead><tbody id="customerRows"></tbody></table></div></div><p class="kv">${esc(p.group||'Hub admins only')} · Response targets follow the request type · Up to 500 matching requests shown</p>`;
    if(typeof api().oncallProjects==='function')api().oncallProjects(token()).then(items=>{
      if(!active(stamp))return;
      const linked=items.find(x=>String(x.scope.customer)===String(p.id));
      const el=root.querySelector('[data-oncall-module]');
      if(el)el.innerHTML=linked?`<nav class="customer-settings-nav" aria-label="Project modules"><a class="button" href="#/oncall/${linked.id}">On-call · View coverage →</a></nav>`:getMe().role==='admin'?`<p><a href="#/oncall/new/customer-${p.id}">Set up on-call for this project →</a></p>`:'';
    }).catch(()=>{if(active(stamp)){const el=root.querySelector('[data-oncall-module]');if(el)el.textContent='On-call could not be checked. Refresh to retry.';}});
    let view='open', search='', request=0, timer;
    async function load() {
      const n=++request; notice('Loading…');
      try { const rows=await api().customerProjectTickets(token(),p.id,{view,status:'',queue:'',assignee:'',q:search}); if(!active(stamp)||n!==request)return;
        root.querySelector('#customerRows').innerHTML=rows.map(r=>`<tr><td><span class="request-key">${esc(r.key)}</span><a class="request-title" href="#/t/${r.id}">${esc(r.subject)}</a><span class="rowsub">${esc(r.typeName||'General support')}</span></td><td>${esc(r.requesterName)}<span class="rowsub">${esc(r.requesterEmail)}</span></td><td>${statusPill(r,true)}${r.workflowStep?`<span class="rowsub">${esc(r.workflowStep)}</span>`:''}</td><td>${esc(r.assigneeName||'Not assigned')}${r.breached?'<span class="rowsub due-overdue">Response overdue</span>':''}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No requests in this view.</td></tr>'; notice(`${rows.length} request${rows.length===1?'':'s'}`);
      } catch { if(active(stamp)&&n===request)notice('Could not refresh. Change a filter to retry.'); }
    }
    root.querySelector('#customerFilter').onclick=e=>{const b=e.target.closest('[data-view]');if(!b)return;view=b.dataset.view;root.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));load();};
    root.querySelector('#customerSearch').oninput=e=>{search=e.target.value;clearTimeout(timer);timer=setTimeout(()=>{if(active(stamp))load();},250);};
    await load();
  }
  function editor(p) {
    const fields=(p?.fields||[]).map(f=>({...f}));
    root.innerHTML=`<a class="back-link" href="#/customers${p?'/'+p.id:''}">← ${p?esc(p.name):'Customer projects'}</a><div class="page-heading"><div><span class="eyebrow">CUSTOMER SUPPORT</span><h2>${p?'Project & integrations':'Create a support project'}</h2><p class="lead">Choose who helps. Decide how customers get in.</p></div><a class="button" href="./customer-support.html" target="_blank" rel="noopener">Embedding guide ↗</a></div>${p?`<nav class="customer-settings-nav" aria-label="Project settings"><button type="button" data-jump="customerProjectForm">Project & team</button><a class="button" href="#/customers/${p.id}/types">Request types & workflows →</a><button type="button" data-jump="cpPrivacy">Privacy & retention</button><button type="button" data-jump="cpIntegrations">Embed & API</button></nav>`:''}<form id="customerProjectForm">${section('01 · Your product',`<div class="row"><div>${input('Project name','cpName',p?.name||'','required maxlength="60" placeholder="e.g. Orbit"')}</div><div>${input('Support group from Hub','cpGroup',p?.group||'','list="groupList" maxlength="80" placeholder="Blank = Hub admins only"')}</div></div><label for="cpDescription">Short introduction shown to customers</label><textarea id="cpDescription" maxlength="300" rows="2">${esc(p?.description||'')}</textarea><p class="kv">Group members also need the Desk Agent role in Hub. Owners and Desk admins always have access.</p><label class="checkline"><input type="checkbox" id="cpEnabled" ${!p||p.enabled?'checked':''}> Accept new requests</label>`)}${p?section('02 · Request types & workflows',`<p>Give each type its own questions, handling steps and service targets.</p><a class="button" href="#/customers/${p.id}/types">Manage request types →</a>`):section('02 · Default request form',`<p class="kv">Name, email, subject and message are included. Add request types and workflows after creating the project.</p><div id="cpFields"></div><button type="button" id="cpAddField">Add a field +</button>`)}${section('03 · Website widget',`<label class="checkline"><input type="checkbox" id="cpWidget" ${p?.widgetEnabled?'checked':''}> Enable public form and widget</label><label for="cpOrigins">Product website origins · one per line</label><textarea id="cpOrigins" rows="2" placeholder="https://product.example.com">${esc((p?.origins||[]).join('\n'))}</textarea><p class="kv">The form is public when enabled. Origins restrict browser integrations, not bots. New requests are limited to 30/hour and 200/day per project.</p>`)}<div class="btnrow"><button class="primary" type="submit">${p?'Save project':'Create project'}</button><span data-status role="status"></span></div></form>${p?'<div id="cpPrivacy"></div><div id="cpIntegrations"></div>':'<p class="kv">Automatic deletion starts with 90 days after completion and 365 days without activity. Adjust privacy settings after creating this project.</p>'}`;
    function paintFields() {
      root.querySelector('#cpFields').innerHTML=fields.map((f,i)=>`<div class="customer-field" data-field="${i}"><div>${input('Label',`cfl${i}`,f.title,'data-prop="title" maxlength="80" required')}</div><div>${input('API key',`cfk${i}`,f.key,'data-prop="key" pattern="[a-z0-9_]+" maxlength="40" required')}</div><div><label for="cft${i}">Type</label><select id="cft${i}" data-prop="kind">${[['text','Short text'],['textarea','Long text'],['select','Choice'],['date','Date'],['bool','Yes / no']].map(([v,l])=>`<option value="${v}"${f.kind===v?' selected':''}>${l}</option>`).join('')}</select></div><label class="checkline"><input type="checkbox" data-prop="required" ${f.required?'checked':''}> Required</label><button type="button" data-remove="${i}" aria-label="Remove ${esc(f.title||'field')}">×</button><div class="customer-options ${f.kind==='select'?'':'hidden'}">${input('Choices · comma separated',`cfo${i}`,f.options.join(', '),'data-prop="options"')}</div></div>`).join('');
      root.querySelector('#cpAddField').disabled=fields.length>=12;
    }
    if(!p){root.querySelector('#cpFields').oninput=e=>{const row=e.target.closest('[data-field]');if(!row)return;const f=fields[Number(row.dataset.field)],k=e.target.dataset.prop;if(!k)return;f[k]=k==='required'?e.target.checked:k==='options'?e.target.value.split(',').map(x=>x.trim()).filter(Boolean):e.target.value;if(k==='kind')row.querySelector('.customer-options').classList.toggle('hidden',f.kind!=='select');};
    root.querySelector('#cpFields').onclick=e=>{const b=e.target.closest('[data-remove]');if(b){fields.splice(Number(b.dataset.remove),1);paintFields();}};
    root.querySelector('#cpAddField').onclick=()=>{fields.push({key:'',title:'',kind:'text',options:[],required:false,sensitive:false});paintFields();};paintFields();}
    root.querySelector('#customerProjectForm').onsubmit=e=>{e.preventDefault();const get=id=>root.querySelector('#'+id);run(e.submitter,()=>api().saveCustomerProject(token(),p?.id||0n,p?.revision||0n,{name:get('cpName').value.trim(),description:get('cpDescription').value.trim(),group:get('cpGroup').value.trim(),enabled:get('cpEnabled').checked,widgetEnabled:get('cpWidget').checked,origins:get('cpOrigins').value.split(/\s+/).filter(Boolean),fields}),r=>{location.hash=`#/customers/${r.id}/settings`;show(String(r.id),'settings');});};
    root.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>root.querySelector('#'+b.dataset.jump)?.scrollIntoView({behavior:'smooth',block:'start'}));
    if(p){const stamp=generation;integrations(p,stamp);void projectPrivacy({el:root.querySelector('#cpPrivacy'),api,token,project:p,active:()=>active(stamp)&&getMe()?.role==='admin'});}
  }
  async function integrations(p,stamp) {
    const el=root.querySelector('#cpIntegrations'), formUrl=`${base()}support.html#form/${p.widgetId}`;
    const snippet=`<script src="${base()}widget.js" data-project="${p.widgetId}" data-label="Contact support" defer></script>`;
    el.innerHTML=section('Embed & API · Connect your website',`<ol class="customer-embed-steps"><li>Add your website’s exact HTTPS origin above.</li><li>Copy this script into your website before &lt;/body&gt;.</li><li>Send a test request and reply from this project.</li></ol><p><a href="./customer-support.html#embedding" target="_blank" rel="noopener">Embedding guide · iframe, API, CSP & troubleshooting ↗</a></p><p>Customers submit a request and receive a private link for replies and status. No account needed.</p><p class="kv">Replies are available through the link. This version does not send customer emails or accept attachments. Ask customers to save their link.</p>${p.widgetEnabled?`<a class="button" target="_blank" rel="noopener noreferrer" href="${esc(formUrl)}">Preview customer form ↗</a><label for="cpEmbed">Paste before your website’s closing &lt;/body&gt; tag</label><textarea id="cpEmbed" rows="3" readonly>${esc(snippet)}</textarea><button type="button" data-copy="cpEmbed">Copy embed code</button><details><summary>Replace the widget address</summary><p>Existing embeds and form links stop accepting requests. Private ticket links continue working.</p><button id="cpRotate" type="button">Replace widget address</button></details>`:'<p class="kv">Enable the widget above to get an embed code. Secret API keys work independently.</p>'}`)+section('Product API',`<p>Keep the secret in your product backend. Each key is limited to this project and the permissions you choose.</p><div id="cpKeys"></div><details><summary>Create an API key</summary><div class="row"><div>${input('Integration name','cpKeyName','','maxlength="60" placeholder="Product backend"')}</div><div>${input('Expires after days','cpKeyDays','90','type="number" min="1" max="365"')}</div></div><div class="customer-scopes"><label class="checkline"><input type="checkbox" value="tickets:create" checked> Create requests</label><label class="checkline"><input type="checkbox" value="tickets:read"> Read customer-visible ticket data</label><label class="checkline"><input type="checkbox" value="tickets:reply"> Reply as the customer</label></div><button type="button" id="cpCreateKey">Create key</button><div id="cpSecret" role="status"></div></details><details><summary>API reference & fields</summary><p><code>${esc(service)}/projects/${p.id}</code></p><p><code>GET /schema</code> returns the current revision, defaultTypeId and requestTypes with their fields. Send typeId to select a type; omitting it uses the default. <code>POST /tickets</code> creates a request; <code>GET /tickets/{id}</code> reads it; <code>POST /tickets/{id}/replies</code> adds a customer reply.</p><p>No internal notes, staff identities or Hub data are exposed. Read and reply permissions cover any ticket in this project whose ID the integration knows.</p><pre>${esc(JSON.stringify({name:'Alex Example',email:'alex@example.com',subject:'Help with my order',body:'Here is what happened…',revision:Number(p.revision),typeId:Number(p.typeId),clientToken:'GENERATE_32_RANDOM_BYTES_AS_64_HEX_CHARACTERS',fields:Object.fromEntries(p.fields.map(f=>[f.key,f.kind==='select'?f.options[0]:'']))},null,2))}</pre><p class="kv">Authenticate with Authorization: Bearer YOUR_SECRET. Keep clientToken private: it provides the customer’s ticket access and makes exact request retries safe. Never reuse it for another request.</p><a href="./customer-support.html" target="_blank" rel="noopener">Full integration guide ↗</a></details>`);
    el.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>run(b,async()=>{await navigator.clipboard.writeText(root.querySelector('#'+b.dataset.copy).value);return true;}));
    const rotate=el.querySelector('#cpRotate');if(rotate)rotate.onclick=()=>run(rotate,()=>api().rotateCustomerWidget(token(),p.id),()=>show(String(p.id),'settings'));
    async function keys() {
      const items=await api().customerProjectKeys(token(),p.id);if(!active(stamp))return;
      el.querySelector('#cpKeys').innerHTML=items.map(k=>`<div class="customer-key"><div><strong>${esc(k.name)}</strong><span class="rowsub">${esc(k.scopes.join(' · '))}<br>${k.revoked?'Revoked':'Expires '+new Date(Number(k.expiresAt/1000000n)).toLocaleDateString()}</span></div>${!k.revoked?`<button type="button" data-revoke="${k.id}">Revoke</button>`:''}</div>`).join('')||'<p class="kv">No API keys yet.</p>';
      el.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=()=>run(b,()=>api().revokeCustomerKey(token(),BigInt(b.dataset.revoke)),keys));
    }
    el.querySelector('#cpCreateKey').onclick=e=>run(e.currentTarget,()=>api().createCustomerKey(token(),p.id,el.querySelector('#cpKeyName').value,[...el.querySelectorAll('.customer-scopes input:checked')].map(x=>x.value),BigInt(Number(el.querySelector('#cpKeyDays').value)||0)),async r=>{
      el.querySelector('#cpSecret').innerHTML=`<p>Copy now. This secret will not be shown again.</p><label for="cpNewSecret">API secret</label><input type="text" readonly id="cpNewSecret" value="${esc(r.secret)}" autocomplete="off"><button type="button" id="cpCopySecret">Copy & hide</button>`;
      el.querySelector('#cpCopySecret').onclick=e=>run(e.currentTarget,async()=>{await navigator.clipboard.writeText(r.secret);el.querySelector('#cpSecret').textContent='Secret copied.';});await keys();
    });
    try { await keys(); } catch { if(active(stamp))notice('Could not load API keys. Reload this project.'); }
  }
  return {show,clear};
}
